PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS visits(id TEXT PRIMARY KEY,first_seen INTEGER NOT NULL,last_seen INTEGER NOT NULL,source TEXT NOT NULL,entry_stage TEXT NOT NULL,last_stage TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS visits_last ON visits(last_seen);
CREATE INDEX IF NOT EXISTS visits_first ON visits(first_seen);
CREATE TABLE IF NOT EXISTS visit_events(id INTEGER PRIMARY KEY AUTOINCREMENT,visit_id TEXT NOT NULL REFERENCES visits(id) ON DELETE CASCADE,stage TEXT NOT NULL,at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS visit_events_visit ON visit_events(visit_id,id);
CREATE TABLE IF NOT EXISTS sessions(id TEXT PRIMARY KEY,email_hash TEXT,role TEXT NOT NULL DEFAULT 'customer',expires INTEGER NOT NULL,created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS challenges(id TEXT PRIMARY KEY,email_hash TEXT NOT NULL,email_enc TEXT NOT NULL,code_hash TEXT NOT NULL,session_id TEXT NOT NULL,expires INTEGER NOT NULL,attempts INTEGER NOT NULL DEFAULT 0,consumed INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS readings(id TEXT PRIMARY KEY,session_id TEXT NOT NULL,age_category TEXT NOT NULL,input_enc TEXT NOT NULL,chart_enc TEXT NOT NULL,preview_enc TEXT NOT NULL,created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS visit_readings(visit_id TEXT NOT NULL REFERENCES visits(id) ON DELETE CASCADE,reading_id TEXT NOT NULL REFERENCES readings(id) ON DELETE CASCADE,PRIMARY KEY(visit_id,reading_id));
CREATE TABLE IF NOT EXISTS orders(id TEXT PRIMARY KEY,reading_id TEXT NOT NULL REFERENCES readings(id),email_hash TEXT NOT NULL,email_enc TEXT NOT NULL,amount INTEGER NOT NULL CHECK(amount IN (22000,33000)),payment_status TEXT NOT NULL CHECK(payment_status IN ('pending','paid','refund_pending','refunded')),fulfillment TEXT NOT NULL CHECK(fulfillment IN ('waiting','queued','generating','ready','retrying','failed')),payment_key TEXT UNIQUE,created INTEGER NOT NULL,paid_at INTEGER,expires INTEGER,version INTEGER NOT NULL DEFAULT 1,corrections INTEGER NOT NULL DEFAULT 0,content_deleted INTEGER NOT NULL DEFAULT 0,consent_enc TEXT NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS one_active_order ON orders(reading_id,email_hash) WHERE payment_status!='refunded';
CREATE TABLE IF NOT EXISTS pg_ledger(payment_key TEXT PRIMARY KEY,order_id TEXT NOT NULL UNIQUE,amount INTEGER NOT NULL,status TEXT NOT NULL,cancel_id TEXT);
CREATE TABLE IF NOT EXISTS jobs(id TEXT PRIMARY KEY,order_id TEXT NOT NULL REFERENCES orders(id),version INTEGER NOT NULL,state TEXT NOT NULL,attempts INTEGER NOT NULL DEFAULT 0,scheduled INTEGER NOT NULL,lease_until INTEGER,error TEXT,UNIQUE(order_id,version));
CREATE TABLE IF NOT EXISTS reports(id TEXT PRIMARY KEY,order_id TEXT NOT NULL REFERENCES orders(id),version INTEGER NOT NULL,payload TEXT NOT NULL,created INTEGER NOT NULL,UNIQUE(order_id,version));
CREATE TABLE IF NOT EXISTS outbox(id TEXT PRIMARY KEY,email_hash TEXT NOT NULL,payload TEXT NOT NULL,created INTEGER NOT NULL,status TEXT NOT NULL DEFAULT 'local_only');
CREATE TABLE IF NOT EXISTS tickets(id TEXT PRIMARY KEY,email_hash TEXT NOT NULL,order_id TEXT,category TEXT NOT NULL,payload TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'open',created INTEGER NOT NULL,due INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS refunds(id TEXT PRIMARY KEY,order_id TEXT NOT NULL UNIQUE REFERENCES orders(id),amount INTEGER NOT NULL,reason_enc TEXT NOT NULL,status TEXT NOT NULL,cancel_id TEXT,created INTEGER NOT NULL,resolved INTEGER);
CREATE TABLE IF NOT EXISTS audit(id INTEGER PRIMARY KEY AUTOINCREMENT,actor TEXT NOT NULL,action TEXT NOT NULL,target TEXT NOT NULL,created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS events(id TEXT PRIMARY KEY,event TEXT NOT NULL,target TEXT NOT NULL,created INTEGER NOT NULL,UNIQUE(event,target));
CREATE TABLE IF NOT EXISTS rate_limits(key TEXT PRIMARY KEY,count INTEGER NOT NULL,reset INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS orders_email ON orders(email_hash);
CREATE INDEX IF NOT EXISTS jobs_due ON jobs(state,scheduled);
CREATE INDEX IF NOT EXISTS outbox_email ON outbox(email_hash,created);
CREATE TABLE IF NOT EXISTS schema_migrations(version INTEGER PRIMARY KEY,applied INTEGER NOT NULL);
INSERT OR IGNORE INTO schema_migrations VALUES(1,unixepoch()*1000);

CREATE TABLE IF NOT EXISTS reading_history(order_id TEXT NOT NULL REFERENCES orders(id) ON DELETE CASCADE,reading_id TEXT NOT NULL REFERENCES readings(id),version INTEGER NOT NULL,PRIMARY KEY(order_id,version));

CREATE TABLE IF NOT EXISTS admin_auth(session_id TEXT PRIMARY KEY REFERENCES sessions(id) ON DELETE CASCADE,verified_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS admin_totp_replay(operator_key TEXT PRIMARY KEY,last_step INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS deletion_tombstones(order_id TEXT PRIMARY KEY,deleted_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS worker_heartbeat(name TEXT PRIMARY KEY,updated INTEGER NOT NULL);
INSERT OR IGNORE INTO schema_migrations VALUES(2,unixepoch()*1000);
CREATE TABLE IF NOT EXISTS email_changes(id TEXT PRIMARY KEY,order_id TEXT NOT NULL REFERENCES orders(id),old_hash TEXT NOT NULL,new_hash TEXT NOT NULL,new_email_enc TEXT NOT NULL,session_id TEXT NOT NULL,code_hash TEXT NOT NULL,expires INTEGER NOT NULL,attempts INTEGER NOT NULL DEFAULT 0,state TEXT NOT NULL DEFAULT 'pending');
INSERT OR IGNORE INTO schema_migrations VALUES(3,unixepoch()*1000);
CREATE TABLE IF NOT EXISTS session_auth(session_id TEXT PRIMARY KEY REFERENCES sessions(id) ON DELETE CASCADE,verified_at INTEGER NOT NULL);
INSERT OR IGNORE INTO schema_migrations VALUES(4,unixepoch()*1000);
CREATE TABLE IF NOT EXISTS toss_attempts(order_id TEXT PRIMARY KEY REFERENCES orders(id),payment_key TEXT NOT NULL UNIQUE,merchant_id TEXT NOT NULL,state TEXT NOT NULL CHECK(state IN ('confirming','uncertain','verified','refunded','review')),generation INTEGER NOT NULL DEFAULT 0,lease_until INTEGER NOT NULL DEFAULT 0,needs_check INTEGER NOT NULL DEFAULT 0,approved_at INTEGER,refund_reason_enc TEXT NOT NULL,refund_dispatched INTEGER NOT NULL DEFAULT 0,last_error TEXT,last_status TEXT,checked_at INTEGER,failures INTEGER NOT NULL DEFAULT 0,next_check INTEGER NOT NULL DEFAULT 0,created INTEGER NOT NULL,updated INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS toss_notifications(id INTEGER PRIMARY KEY AUTOINCREMENT,event_key TEXT NOT NULL UNIQUE,order_id TEXT NOT NULL REFERENCES orders(id),received INTEGER NOT NULL,processed INTEGER);
CREATE INDEX IF NOT EXISTS toss_recovery_due ON toss_attempts(needs_check,state,lease_until);
INSERT OR IGNORE INTO schema_migrations VALUES(5,unixepoch()*1000);
CREATE TABLE IF NOT EXISTS ticket_contacts(ticket_id TEXT PRIMARY KEY REFERENCES tickets(id) ON DELETE CASCADE,email_enc TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS mail_queue(outbox_id TEXT PRIMARY KEY REFERENCES outbox(id) ON DELETE CASCADE,recipient_enc TEXT NOT NULL,message_enc TEXT NOT NULL,template TEXT NOT NULL,state TEXT NOT NULL DEFAULT 'local_only',profile_digest TEXT,provider_id TEXT,generation INTEGER NOT NULL DEFAULT 0,lease_until INTEGER NOT NULL DEFAULT 0,attempts INTEGER NOT NULL DEFAULT 0,failures INTEGER NOT NULL DEFAULT 0,recovery_hold INTEGER NOT NULL DEFAULT 0,scheduled INTEGER NOT NULL DEFAULT 0,first_dispatched INTEGER,deadline INTEGER,needs_check INTEGER NOT NULL DEFAULT 0,last_error TEXT,updated INTEGER NOT NULL,UNIQUE(profile_digest,provider_id));
CREATE TABLE IF NOT EXISTS mail_notifications(id INTEGER PRIMARY KEY AUTOINCREMENT,event_key TEXT NOT NULL UNIQUE,outbox_id TEXT NOT NULL REFERENCES outbox(id) ON DELETE CASCADE,received INTEGER NOT NULL,processed INTEGER);
CREATE INDEX IF NOT EXISTS mail_queue_due ON mail_queue(state,scheduled,lease_until);
CREATE INDEX IF NOT EXISTS challenges_email ON challenges(email_hash);
CREATE INDEX IF NOT EXISTS tickets_email ON tickets(email_hash);
INSERT OR IGNORE INTO schema_migrations VALUES(6,unixepoch()*1000);
CREATE TABLE IF NOT EXISTS mail_suppressions(email_hash TEXT PRIMARY KEY,reason TEXT NOT NULL,created INTEGER NOT NULL);

CREATE TABLE IF NOT EXISTS report_usage(order_id TEXT NOT NULL REFERENCES orders(id) ON DELETE CASCADE,version INTEGER NOT NULL,provider TEXT NOT NULL,input_tokens INTEGER NOT NULL CHECK(input_tokens>=0),output_tokens INTEGER NOT NULL CHECK(output_tokens>=0),estimated_usd_micros INTEGER CHECK(estimated_usd_micros>=0),PRIMARY KEY(order_id,version));
INSERT OR IGNORE INTO schema_migrations VALUES(7,unixepoch()*1000);

CREATE TABLE IF NOT EXISTS privacy_checkpoint_source(id INTEGER PRIMARY KEY CHECK(id=1),source_id TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS privacy_checkpoint_health(id INTEGER PRIMARY KEY CHECK(id=1),generated_at INTEGER NOT NULL,last_failure INTEGER);
INSERT OR IGNORE INTO schema_migrations VALUES(9,unixepoch()*1000);
CREATE TABLE IF NOT EXISTS order_generation_lanes(order_id TEXT PRIMARY KEY REFERENCES orders(id) ON DELETE CASCADE,provider TEXT NOT NULL CHECK(provider='openai'),assigned_version INTEGER NOT NULL CHECK(assigned_version>0),created INTEGER NOT NULL);

CREATE TABLE IF NOT EXISTS admin_credentials(id INTEGER PRIMARY KEY CHECK(id=1),digest TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS visit_networks(visit_id TEXT PRIMARY KEY REFERENCES visits(id) ON DELETE CASCADE,network_key TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS visit_networks_key ON visit_networks(network_key);
CREATE TABLE IF NOT EXISTS visit_exclusions(network_key TEXT PRIMARY KEY,expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS sales_ai_holds(order_id TEXT PRIMARY KEY REFERENCES orders(id) ON DELETE CASCADE,version INTEGER NOT NULL,day TEXT NOT NULL,reserved INTEGER NOT NULL,expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS ai_generation_evidence(order_id TEXT NOT NULL REFERENCES orders(id) ON DELETE CASCADE,version INTEGER NOT NULL,response_enc TEXT NOT NULL,created INTEGER NOT NULL,PRIMARY KEY(order_id,version));
CREATE TABLE IF NOT EXISTS taehou_counsel(id TEXT PRIMARY KEY,order_id TEXT NOT NULL REFERENCES orders(id) ON DELETE CASCADE,number INTEGER NOT NULL CHECK(number BETWEEN 1 AND 3),report_version INTEGER NOT NULL,reservation_id TEXT NOT NULL UNIQUE,request_id TEXT NOT NULL,question_enc TEXT NOT NULL,answer_enc TEXT,response_enc TEXT,state TEXT NOT NULL CHECK(state IN ('queued','working','answered','failed')),created INTEGER NOT NULL,started INTEGER,error TEXT,UNIQUE(order_id,number),UNIQUE(order_id,request_id));
CREATE TABLE IF NOT EXISTS report_access_events(id TEXT PRIMARY KEY,order_id TEXT NOT NULL REFERENCES orders(id) ON DELETE CASCADE,kind TEXT NOT NULL CHECK(kind IN ('viewed','web_error','pdf_error','client_error','blocked')),code TEXT,created INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS report_access_order_time ON report_access_events(order_id,created);
